#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    long long maximumSubarraySum(std::vector<int>& nums, int k) {
        long long pref = 0;
        std::unordered_map<int, long long> min_pref;
        long long ans = -1e18;
        for (int x : nums) {
            if (min_pref.count(x)) min_pref[x] = std::min(min_pref[x], pref);
            else min_pref[x] = pref;
            pref += x;
            if (min_pref.count(x - k)) ans = std::max(ans, pref - min_pref[x - k]);
            if (min_pref.count(x + k)) ans = std::max(ans, pref - min_pref[x + k]);
        }
        return ans == -1e18 ? 0 : ans;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public long maximumSubarraySum(int[] nums, int k) {
        long pref = 0;
        Map<Integer, Long> minPref = new HashMap<>();
        long ans = Long.MIN_VALUE;
        for (int x : nums) {
            if (minPref.containsKey(x)) minPref.put(x, Math.min(minPref.get(x), pref));
            else minPref.put(x, pref);
            pref += x;
            if (minPref.containsKey(x - k)) ans = Math.max(ans, pref - minPref.get(x - k));
            if (minPref.containsKey(x + k)) ans = Math.max(ans, pref - minPref.get(x + k));
        }
        return ans == Long.MIN_VALUE ? 0 : ans;
    }
}

var maximumSubarraySum = function(nums, k) {
    let pref = 0;
    const minPref = new Map();
    let ans = -Infinity;
    for (const x of nums) {
        if (minPref.has(x)) minPref.set(x, Math.min(minPref.get(x), pref));
        else minPref.set(x, pref);
        pref += x;
        if (minPref.has(x - k)) ans = Math.max(ans, pref - minPref.get(x - k));
        if (minPref.has(x + k)) ans = Math.max(ans, pref - minPref.get(x + k));
    }
    return ans === -Infinity ? 0 : ans;
};
